#!/usr/bin/env node
"use strict";

// Build host interfaces from maintained sources. Runtime consumers need no npm packages.
const fs = require("node:fs");
const path = require("node:path");
const crypto = require("node:crypto");
const vm = require("node:vm");
const ROOT = path.resolve(__dirname, "..");
const hash = (bytes) => crypto.createHash("sha256").update(bytes).digest("hex");
const read = (name) => fs.readFileSync(path.join(ROOT, name), "utf8");
const GENERATED =
    "// Generated by scripts/build.cjs. Edit src/, then rebuild.\n";

function mix(bg, fg, weight) {
    const channel = (hex, i) => parseInt(hex.slice(i, i + 2), 16);
    return (
        "#" +
        [1, 3, 5]
            .map((i) =>
                Math.round(
                    channel(bg, i) * weight + channel(fg, i) * (1 - weight),
                )
                    .toString(16)
                    .padStart(2, "0"),
            )
            .join("")
    );
}

function validateTheme(theme) {
    const names = new Set();
    for (const slot of theme.slots) {
        if (
            !/^[a-z][a-z0-9-]*$/.test(slot.id) ||
            names.has(slot.id) ||
            ["system", "editor"].includes(slot.id)
        )
            throw new Error("Invalid or duplicate palette: " + slot.id);
        names.add(slot.id);
        if (
            !["light", "dark"].includes(slot.mode) ||
            !/^#[0-9a-f]{6}$/i.test(slot.bg) ||
            !/^#[0-9a-f]{6}$/i.test(slot.fg) ||
            !slot.label
        )
            throw new Error("Invalid palette: " + slot.id);
    }
    if (
        !names.has(theme.default) ||
        !names.has(theme.dark) ||
        !["sans", "serif", "mono"].includes(theme.documentFont)
    )
        throw new Error("Invalid default theme/font");
    if (
        typeof theme.diagramFont !== "string" ||
        !/^\d+px$/.test(theme.diagramFontSize)
    )
        throw new Error("Invalid diagram typography");
}

function appearance(theme) {
    const light = theme.slots.find((s) => s.id === theme.default);
    const dark = theme.slots.find((s) => s.id === theme.dark);
    const selector = (s) => `body[data-xnote-theme="${s.id}"]`;
    const editor = (mode) =>
        `body[data-xnote-theme="editor"]:has(.markdown-preview.editor-${mode})`;
    const system =
        'body:is(:not([data-xnote-theme]), [data-xnote-theme="system"])';
    const seed = (s) => `--_slot-bg:${s.bg};--_slot-fg:${s.fg};`;
    const properties = {
        "bg-primary": light.bg,
        "text-normal": light.fg,
        "bg-secondary": mix(light.bg, light.fg, 0.95),
        "border-normal": mix(light.bg, light.fg, 0.79),
    };
    const registrations = Object.entries(properties)
        .map(
            ([name, value]) =>
                `@property --${name} {syntax:"<color>";inherits:true;initial-value:${value};}`,
        )
        .join("\n");
    const rules = [
        ":root {--radius-small:3px;--radius-medium:6px;--radius-large:6px;" +
            `#paper-slot-light(${light.bg},${light.fg});}`,
        "html > body {background-color:var(--bg-primary);color:var(--text-normal);transition:background-color .25s ease,color .25s ease;}",
    ];
    const screen = theme.slots.map((s) => `${selector(s)} {${seed(s)}}`);
    screen.push(
        `${editor("light")} {${seed(light)}}`,
        `${editor("dark")} {${seed(dark)}}`,
    );
    for (const mode of ["light", "dark"]) {
        const targets = theme.slots
            .filter((s) => s.mode === mode)
            .map(selector)
            .concat(editor(mode));
        screen.push(
            `${targets.join(",")} {#paper-slot-${mode}(var(--_slot-bg),var(--_slot-fg));color-scheme:${mode};}`,
        );
    }
    screen.push(`${system} {color-scheme:light;}`);
    screen.push(
        `@media (prefers-color-scheme:dark) {${system} {${seed(dark)}#paper-slot-dark(var(--_slot-bg),var(--_slot-fg));color-scheme:dark;}}`,
    );
    const dim = `.markdown-preview img,.markdown-preview svg{filter:brightness(.85);}
    .markdown-preview.invertimg img{filter:invert(.92) hue-rotate(180deg);mix-blend-mode:screen;}
    .mpe-lightbox-overlay img{filter:none;}`;
    screen.push(
        `${theme.slots
            .filter((s) => s.mode === "dark")
            .map(selector)
            .concat(editor("dark"))
            .join(",")} {${dim}}`,
    );
    screen.push(`@media (prefers-color-scheme:dark) {${system} {${dim}}}`);
    const scrollbar = (s) =>
        `scrollbar-color:color-mix(in srgb,${s.bg} ${s.mode === "dark" ? 62 : 66}%,${s.fg}) ${s.bg};`;
    for (const slot of theme.slots)
        screen.push(`html:has(> ${selector(slot)}){${scrollbar(slot)}}`);
    screen.push(
        `html:has(> ${editor("light")}),html:has(> ${system}){${scrollbar(light)}}`,
    );
    screen.push(`html:has(> ${editor("dark")}){${scrollbar(dark)}}`);
    screen.push(
        `@media (prefers-color-scheme:dark){html:has(> ${system}){${scrollbar(dark)}}}`,
    );
    rules.push(`@media screen {${screen.join("\n")}}`);
    const labels = { system: "跟随系统", editor: "跟随编辑器" };
    const dots = { system: [light.bg, dark.bg], editor: [light.bg, dark.bg] };
    for (const s of theme.slots) {
        labels[s.id] = s.label;
        dots[s.id] = [s.bg, s.fg];
    }
    return {
        registrations,
        less: `#xnote-appearance() {${rules.join("\n")}}`,
        script: `var ORDER=${JSON.stringify(["system", "editor", ...theme.slots.map((s) => s.id)])};\nvar LABELS=${JSON.stringify(labels)};\nvar DOTS=${JSON.stringify(dots)};`,
    };
}

// Scope only our prose CSS, leaving component-specific rules and vendor CSS intact.
function scopeProse(css) {
    const postcss = require("postcss");
    const parser = require("postcss-selector-parser");
    const tree = postcss.parse(css);
    tree.walkRules((rule) => {
        if (!rule.selector.includes("markdown-preview")) return;
        rule.selector = parser((selectors) =>
            selectors.each((selector) => {
                let component = false;
                selector.walkClasses((c) => {
                    if (["mermaid", "crossnote-pseudocode"].includes(c.value))
                        component = true;
                });
                if (component) return;
                const gate = parser()
                    .astSync(
                        ":not(:where(.mermaid *, .crossnote-pseudocode *))",
                    )
                    .first.first.clone();
                const pseudoElement = selector.nodes.find(
                    (n) => n.type === "pseudo" && n.value.startsWith("::"),
                );
                if (pseudoElement) selector.insertBefore(pseudoElement, gate);
                else selector.append(gate);
            }),
        ).processSync(rule.selector);
    });
    return tree.toString();
}

function paintCSS(css) {
    const postcss = require("postcss");
    const parser = require("postcss-selector-parser");
    const tree = postcss.parse(css);
    tree.walkRules((rule) => {
        rule.selector = parser((selectors) =>
            selectors.each((selector) => {
                selector.append(
                    parser()
                        .astSync(":not(:where(.native *))")
                        .first.first.clone(),
                );
                selector.append(
                    parser()
                        .astSync(
                            ':where(svg:is([aria-roledescription="flowchart-v2"], [aria-roledescription="sequence"], [aria-roledescription="stateDiagram"], [aria-roledescription="class"], [aria-roledescription="classDiagram"], [aria-roledescription="er"]) *)',
                        )
                        .first.first.clone(),
                );
            }),
        ).processSync(rule.selector);
    });
    return tree.toString();
}

// MPE runs its bundled LESS over style.less again. Escape declaration values
// so an older host compiler does not reinterpret modern native CSS functions.
function hostLess(css) {
    const tree = require("postcss").parse(css);
    tree.walkDecls((decl) => {
        decl.value = "~" + JSON.stringify(decl.value);
    });
    tree.walkAtRules("import", (rule) => {
        rule.params = "(css) " + rule.params;
    });
    return tree.toString();
}

async function outputs() {
    const theme = JSON.parse(read("src/theme.json"));
    validateTheme(theme);
    const app = appearance(theme);
    const core = read("src/parser/pseudocode-core.js");
    const parserCore = `var CROSSNOTE_KATEX_SRC=${JSON.stringify(read("vendor/katex-0.16.47.min.js").trim())};\nvar CROSSNOTE_PSEUDOCODE_SRC=${JSON.stringify(read("vendor/pseudocode-2.4.1.min.js").trim())};\n${core}`;
    const viewerCSS = (
        await require("less").render(read("src/styles/diagram-viewer.less"))
    ).css;
    const result = {
        "parser.js":
            GENERATED +
            read("src/parser/hooks.js").replace(
                "/* @xnote parser-core */",
                () => parserCore,
            ),
        "pseudocode-runtime.js":
            GENERATED +
            read("src/browser/pseudocode-fallback.js").replace(
                "/* @xnote pseudocode-core */",
                () => core,
            ),
        "theme-toggle.js":
            GENERATED +
            read("src/browser/appearance.js").replace(
                "/* @xnote appearance-data */",
                () => app.script,
            ),
        "diagram-actions.js":
            GENERATED +
            read("src/browser/diagram-actions.js").replace(
                "/* @xnote diagram-viewer */",
                () =>
                    read("src/browser/diagram-viewer.js").replace(
                        '/* @xnote viewer-css */ ""',
                        () => JSON.stringify(viewerCSS),
                    ),
            ),
        "head.html":
            "<!-- Generated by scripts/build.cjs. Edit src/head.html. -->\n" +
            read("src/head.html"),
    };
    result["preview.js"] =
        result["theme-toggle.js"] + "\n" + read("src/browser/bootstrap.js");
    const config = JSON.parse(read("src/config.json"));
    config.mermaidConfig.fontFamily = theme.diagramFont;
    config.mermaidConfig.themeVariables = {
        fontFamily: theme.diagramFont,
        fontSize: theme.diagramFontSize,
    };
    config.mermaidConfig.themeCSS = paintCSS(read("src/mermaid/paint.css"));
    result["config.js"] =
        GENERATED + "(" + JSON.stringify(config, null, 2) + ")\n";
    let source = read("src/styles/document.less")
        .replace("/* @xnote color-properties */", () => app.registrations)
        .replace("/* @xnote tokens */", () => read("src/styles/tokens.less"))
        .replace("/* @xnote print */", () => read("src/styles/print.less"));
    source = `@xnote-document-font: ${theme.documentFont};\n` + source;
    source += "\n" + app.less + "\n" + read("src/styles/diagrams.less");
    const compiled = await require("less").render(source, {
        filename: path.join(ROOT, "src/styles/document.less"),
    });
    result["style.less"] =
        "/* Generated by scripts/build.cjs. Edit src/styles/ and src/theme.json. */\n" +
        hostLess(scopeProse(compiled.css));
    for (const [name, content] of Object.entries(result)) {
        if (name.endsWith(".js")) new vm.Script(content, { filename: name });
    }
    const files = {};
    const payload = [
        ...Object.keys(result),
        "README.md",
        "scripts/check-pseudocode.cjs",
        ...fs
            .readdirSync(path.join(ROOT, "vendor"))
            .map((name) => "vendor/" + name),
    ];
    for (const name of payload.sort())
        files[name] = hash(
            result[name] ?? fs.readFileSync(path.join(ROOT, name)),
        );
    result["bundle.json"] =
        JSON.stringify({ version: 1, files }, null, 2) + "\n";
    return result;
}

async function main() {
    if (process.argv.slice(2).some((a) => a !== "--check"))
        throw new Error("Usage: build.cjs [--check]");
    const check = process.argv.includes("--check");
    const expected = await outputs();
    const changed = Object.entries(expected).filter(
        ([name, text]) =>
            !fs.existsSync(path.join(ROOT, name)) || read(name) !== text,
    );
    if (check && changed.length)
        throw new Error(
            "Generated files are stale: " +
                changed.map(([name]) => name).join(", ") +
                ". Run node assets/.crossnote/scripts/build.cjs",
        );
    if (!check)
        for (const [name, text] of changed) {
            const file = path.join(ROOT, name),
                temporary = `${file}.${process.pid}.tmp`;
            try {
                fs.writeFileSync(temporary, text);
                fs.renameSync(temporary, file);
            } finally {
                fs.rmSync(temporary, { force: true });
            }
        }
    console.log(
        check
            ? "Crossnote build is current."
            : `Generated ${changed.length} Crossnote files.`,
    );
}
if (require.main === module)
    main().catch((error) => {
        console.error(error.message);
        process.exitCode = 1;
    });
module.exports = { outputs, scopeProse, paintCSS, hostLess, validateTheme };
